// ===== 1. 取出 ERP 返回的订单数组（兼容几种常见结构）=====
let raw = $json;
if (raw.data !== undefined) raw = raw.data;
if (raw.rows !== undefined) raw = raw.rows;
if (raw.orders !== undefined) raw = raw.orders;
if (raw.items !== undefined) raw = raw.items;
if (raw.result !== undefined && Array.isArray(raw.result)) raw = raw.result;
if (!Array.isArray(raw)) raw = [raw];

// ===== 2. ERP 字段名 → 我们内部字段名（按你 ERP 实际字段改这里）=====
const MAP = {
  '交易编号':   ['交易编号', 'trade_no', 'tradeNo', 'order_no_series'],
  '订单编号':   ['订单编号', 'order_no', 'orderNo', 'shopify_order_no'],
  'SKU':       ['SKU', 'sku', 'sku_code', 'item_sku'],
  '商品数量':   ['商品数量', 'qty', 'quantity', 'num'],
  '国家中文':   ['国家中文', 'country', 'country_cn', 'country_name'],
  '物流公司':   ['物流公司', 'logistics_company', 'carrier'],
  '物流渠道':   ['物流渠道', 'logistics_channel', 'channel', 'shipping_method'],
  '内部单号':   ['内部单号', 'inner_no', 'tracking_no', 'tracking_number'],
  '邮政编码':   ['邮政编码', 'postcode', 'zip', 'zip_code'],
  '原始图片':   ['原始图片', 'image', 'image_url', 'picture']
};

const pick = (row, names) => {
  for (const n of names) {
    if (row[n] !== undefined && row[n] !== null && String(row[n]).trim() !== '') return row[n];
  }
  return '';
};

const rows = raw.map(r => {
  const o = {};
  for (const [target, names] of Object.entries(MAP)) o[target] = pick(r, names);
  return o;
});

// ===== 3. 基本校验：没有 SKU / 没有交易编号 直接报错 =====
const badSku = rows.filter(r => !String(r['SKU']).trim()).length;
const badTxn = rows.filter(r => !String(r['交易编号']).trim()).length;
if (!rows.length) throw new Error('ERP 返回 0 条订单');
if (badSku) throw new Error(`有 ${badSku} 行没有 SKU，检查字段映射`);
if (badTxn) throw new Error(`有 ${badTxn} 行没有交易编号，检查字段映射`);

// ===== 4. 落成一个 JSON 文件 =====
const ts = new Date().toISOString().replace(/[-:T]/g, '').slice(0, 14);
const fileName = `${$('配置').item.json.orders_dir}/erp_orders_${ts}.json`;

return [{
  json: {
    rows: rows.length,
    orders: new Set(rows.map(r => r['交易编号'])).size,
    fileName: fileName,
    sample: rows[0]
  }
}];

// 把上一步规范化后的 rows 再取一次（这里重新做一遍，避免跨节点传大对象）
let raw = $('① 拉 ERP 订单').first().json;
if (raw.data !== undefined) raw = raw.data;
if (raw.rows !== undefined) raw = raw.rows;
if (raw.orders !== undefined) raw = raw.orders;
if (raw.items !== undefined) raw = raw.items;
if (raw.result !== undefined && Array.isArray(raw.result)) raw = raw.result;
if (!Array.isArray(raw)) raw = [raw];

const MAP = {
  '交易编号':   ['交易编号', 'trade_no', 'tradeNo', 'order_no_series'],
  '订单编号':   ['订单编号', 'order_no', 'orderNo', 'shopify_order_no'],
  'SKU':       ['SKU', 'sku', 'sku_code', 'item_sku'],
  '商品数量':   ['商品数量', 'qty', 'quantity', 'num'],
  '国家中文':   ['国家中文', 'country', 'country_cn', 'country_name'],
  '物流公司':   ['物流公司', 'logistics_company', 'carrier'],
  '物流渠道':   ['物流渠道', 'logistics_channel', 'channel', 'shipping_method'],
  '内部单号':   ['内部单号', 'inner_no', 'tracking_no', 'tracking_number'],
  '邮政编码':   ['邮政编码', 'postcode', 'zip', 'zip_code'],
  '原始图片':   ['原始图片', 'image', 'image_url', 'picture']
};
const pick = (row, names) => {
  for (const n of names) {
    if (row[n] !== undefined && row[n] !== null && String(row[n]).trim() !== '') return String(row[n]);
  }
  return '';
};
const rows = raw.map(r => {
  const o = {};
  for (const [t, names] of Object.entries(MAP)) o[t] = pick(r, names);
  return o;
});

// 存成二进制，交给 Read/Write Files 落盘
return [{
  json: { fileName: $('② 字段映射+校验').first().json.fileName, rows: rows.length },
  binary: {
    data: {
      data: Buffer.from(JSON.stringify(rows), 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: $('② 字段映射+校验').first().json.fileName
    }
  }
}];

const r = $json;
const out = (r.stdout || '').trim();
const err = (r.stderr || '').trim();
if (r.code !== 0) throw new Error('匹配失败：' + err.split('\n').slice(-6).join(' | '));

const line = out.split('\n').find(l => l.startsWith('RESULT '));
if (!line) throw new Error('没有 RESULT 输出：' + out.slice(-400));
const res = JSON.parse(line.slice(7));

const missing = [...(res.missing_sku || []), ...(res.missing_rate || [])];
return [{
  json: {
    ok: res.ok,
    source: res.source,
    orders: res.orders,
    rows: res.rows,
    steps: res.steps,
    totalMissing: missing.length,
    missing,
    orderFile: res.order
  }
}];

const existing = new Set();
try {
  const it = $('⑦ 读待补表已有').first().json;
  for (const rec of (it.items || [])) {
    const f = rec.fields || {};
    let key = f['标识'];
    if (Array.isArray(key)) key = key[0]?.text ?? key[0];
    if (key) existing.add(String(key).trim());
  }
} catch (e) {}

const p = $('⑥ 解析缺失').first().json;
const todo = (p.missing || []).filter(m => !existing.has(String(m['标识']).trim()));

// 提醒文案：前 5 条
text = `【60103 配置待补】${p.orders} 单里有 ${p.totalMissing} 项匹配不到：\n`
  + (p.missing || []).slice(0, 5).map(m => `· ${m['类型']}｜${m['标识']}｜${m['说明']}`).join('\n')
  + ((p.missing || []).length > 5 ? `\n… 共 ${p.missing.length} 项，详见「待补配置」表` : '');

return [{
  json: {
    totalMissing: p.totalMissing,
    newCount: todo.length,
    skipped: (p.missing || []).length - todo.length,
    records: todo.map(m => ({
      fields: {
        '类型': m['类型'],
        '标识': m['标识'],
        '建议前缀': m['建议前缀'] || '',
        '订单数': m['订单数'] ?? 0,
        '行数': m['行数'] ?? 0,
        '样例交易编号': m['样例交易编号'] || '',
        'SKU样例': m['SKU样例'] || '',
        '说明': m['说明'] || '',
        '状态': '待处理'
      }
    })),
    text: text,
    orders: p.orders,
    orderFile: p.orderFile,
    steps: p.steps
  }
}];

const p = $('⑧ 过滤+准备提醒').first().json;
return [{
  json: {
    ok: true,
    result: '缺配置，已提醒业务',
    orders: p.orders,
    totalMissing: p.totalMissing,
    newWritten: p.newCount,
    skipped: p.skipped,
    steps: p.steps,
    next: '业务补完商品配置/运价表后重新执行本流程'
  }
}];

const r = $json;
const out = (r.stdout || '').trim();
const err = (r.stderr || '').trim();
if (r.code !== 0) throw new Error('生成计算表失败：' + err.split('\n').slice(-6).join(' | '));

const line = out.split('\n').find(l => l.startsWith('RESULT '));
const res = line ? JSON.parse(line.slice(7)) : {};
return [{
  json: {
    ok: Boolean(res.ok),
    result: '已生成计算表',
    orders: res.orders,
    rows: res.rows,
    issues: res.issues,
    bill_total: res.bill_total,
    out: res.out
  }
}];
